180: # Replaces $Path with $Text (UTF-8, no BOM) atomically: the text is written and flushed
181: # to disk (FileStream.Flush($true)) in a temp file .<name>.<guid>.tmp NEXT TO the
182: # destination (same volume), which then replaces the destination in ONE rename:
183: #   PowerShell 7 (Windows, macOS, Linux)  [IO.File]::Move($tmp, $dst, $true) - on
184: #       Windows MoveFileEx(MOVEFILE_REPLACE_EXISTING), elsewhere rename(2)
185: #   Windows PowerShell 5.1                MoveFileExW(MOVEFILE_REPLACE_EXISTING |
186: #       MOVEFILE_WRITE_THROUGH) through Test-NativeMove; only if Add-Type fails, the old
187: #       path: File.Move when the destination does not exist, else File.Replace
188: #       (ReplaceFile - NOT one atomic step: a process killed inside it can leave the
189: #       destination missing and the new text in the temp file)
190: # A crash leaves either the old or the new file, never a truncated or a missing one (at
191: # worst a stray .<name>.<guid>.tmp next to it). A rename that keeps failing (a reader
192: # holding the destination open without FileShare.Delete) is retried, then the temp file
193: # is removed and the error thrown.
194: function Write-TextAtomic {
195:     param([string]$Path, [string]$Text)
196:     $full = [IO.Path]::GetFullPath($Path)
197:     $dir = [IO.Path]::GetDirectoryName($full)
198:     $tmp = Join-Path $dir ('.' + [IO.Path]::GetFileName($full) + '.' + [guid]::NewGuid().ToString('N') + '.tmp')
199:     $bytes = $script:Utf8NoBom.GetBytes($Text)
200:     $fs = New-Object System.IO.FileStream($tmp, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
201:     try {
202:         $fs.Write($bytes, 0, $bytes.Length)
203:         $fs.Flush($true)
204:     } finally { $fs.Dispose() }
205:     $lastError = $null
206:     for ($attempt = 1; $attempt -le 8; $attempt++) {
207:         try {
208:             if (-not $script:LegacyPS) {
209:                 [IO.File]::Move($tmp, $full, $true)
210:             } elseif (Test-NativeMove) {
211:                 # MOVEFILE_REPLACE_EXISTING (0x1) | MOVEFILE_WRITE_THROUGH (0x8)
212:                 if (-not [CodexConsultNative]::MoveFileEx($tmp, $full, 0x9)) {
213:                     throw (New-Object System.ComponentModel.Win32Exception([Runtime.InteropServices.Marshal]::GetLastWin32Error()))
214:                 }
215:             } elseif (-not [IO.File]::Exists($full)) {
216:                 [IO.File]::Move($tmp, $full)
217:             } else {
218:                 # Fallback only when Add-Type failed (see above): not one atomic step.
219:                 # $null would reach .NET as '' - NullString is a real null (no backup file).
220:                 [IO.File]::Replace($tmp, $full, [System.Management.Automation.Language.NullString]::Value)
221:             }
222:             return
223:         } catch {
224:             # A reader holding the destination open without FileShare.Delete makes the
225:             # rename fail with a sharing violation; it is gone a moment later.
226:             $lastError = $_.Exception
227:             Start-Sleep -Milliseconds 250
228:         }
229:     }
230:     try { [IO.File]::Delete($tmp) } catch { }
231:     throw "could not replace '$full': $($lastError.Message)"
232: }
